162	// ---------------------------------------------------------------------------
163	// Sprint 2: Agent-run SSE streaming
164	// ---------------------------------------------------------------------------
165	
166	export interface AgentRunHandlers {
167	  onActionCard?: (action: AgentAction) => void;
168	  onActionProposal?: (proposal: Record<string, unknown>) => void;
169	  onDelta?: (text: string) => void;
170	  onDone?: (payload: { runId: string; ticketId: string; turns: number }) => void;
171	  onError?: (err: unknown) => void;
172	  signal?: AbortSignal;
173	}
174	
175	export const agentRun = {
176	  /**
177	   * POST /api/tickets/{id}/agent-run → text/event-stream
178	   * Streams action_card + delta + done events while persisting actions to DB.
179	   */
180	  stream: async (
181	    ticketId: string,
182	    handlers: AgentRunHandlers,
183	    promptHint?: string
184	  ): Promise<void> => {
185	    const url = buildUrl(`/api/tickets/${encodeURIComponent(ticketId)}/agent-run`);
186	    const res = await fetch(url, {
187	      method: "POST",
188	      headers: { "Content-Type": "application/json", "Accept": "text/event-stream" },
189	      body: JSON.stringify(promptHint ? { promptHint } : {}),
190	      signal: handlers.signal,
191	    });
192	
193	    if (!res.ok || !res.body) {
194	      const env: ApiErrorEnvelope = {
195	        error: `Agent run failed (${res.status})`,
196	        code: "HTTP_ERROR",
197	        status: res.status,
198	      };
199	      try {
200	        const parsed = await res.json();
201	        if (parsed && typeof parsed === "object" && "error" in parsed) {
202	          Object.assign(env, parsed);
203	        }
204	      } catch { /* ignore */ }
205	      throw new ApiError(env, `/api/tickets/${ticketId}/agent-run`);
206	    }
207	
208	    const reader = res.body.getReader();
209	    const decoder = new TextDecoder("utf-8");
210	    let buffer = "";
211	
212	    try {
213	      while (true) {
214	        const { value, done } = await reader.read();
215	        if (done) break;
216	        buffer += decoder.decode(value, { stream: true });
217	
218	        let sep: number;
219	        while ((sep = buffer.indexOf("\n\n")) !== -1) {
220	          const frame = buffer.slice(0, sep);
221	          buffer = buffer.slice(sep + 2);
222	          parseAgentRunFrame(frame, handlers);
223	        }
224	      }
225	      if (buffer.trim().length > 0) parseAgentRunFrame(buffer, handlers);
226	    } catch (err) {
227	      handlers.onError?.(err);
228	      throw err;
229	    }
230	  },
231	};
232	
233	function parseAgentRunFrame(frame: string, handlers: AgentRunHandlers): void {
234	  let event = "message";
235	  const dataLines: string[] = [];
236	  for (const line of frame.split("\n")) {
237	    if (line.startsWith("event:")) event = line.slice(6).trim();
238	    else if (line.startsWith("data:")) dataLines.push(line.slice(5).trim());
239	  }
240	  if (dataLines.length === 0) return;
241	  const raw = dataLines.join("\n");
242	  let parsed: any;
243	  try { parsed = JSON.parse(raw); } catch { parsed = {}; }
244	
245	  if (event === "action_card") handlers.onActionCard?.(parsed as AgentAction);
246	  else if (event === "action_proposal") handlers.onActionProposal?.(parsed);
247	  else if (event === "delta") handlers.onDelta?.(parsed.text ?? "");
248	  else if (event === "done") handlers.onDone?.(parsed);
249	  else if (event === "error") handlers.onError?.(parsed);
250	}
