291	export const escalations = {
292	  list: () => request<Ticket[]>("/api/escalations"),
293	};
294	
295	/**
296	 * Confirm a proposed agent action by calling the envelope's confirmEndpoint.
297	 * Uses the same request() helper as the rest of the API client — meaning it
298	 * throws ApiError on non-2xx responses and respects NEXT_PUBLIC_BACKEND_URL.
299	 */
300	export function confirmAction(envelope: {
301	  confirmEndpoint: string;
302	  confirmMethod?: string | null;
303	  confirmBody?: Record<string, unknown> | null;
304	}): Promise<unknown> {
305	  return request(envelope.confirmEndpoint, {
306	    method: (envelope.confirmMethod || "POST") as RequestInit["method"],
307	    body: envelope.confirmBody ?? {},
308	  });
309	}
